CREATE TABLE seller_profile (id BIGINT PRIMARY KEY REFERENCES identity_users(id), shop_name VARCHAR(150) NOT NULL, phone VARCHAR(30) NOT NULL, address VARCHAR(500) NOT NULL, status VARCHAR(20) NOT NULL CHECK(status IN ('PENDING','APPROVED','REJECTED')), version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE category (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE book (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, seller_id BIGINT NOT NULL REFERENCES seller_profile(id), title VARCHAR(255) NOT NULL, author VARCHAR(255) NOT NULL, price NUMERIC(12,2) NOT NULL CHECK(price>0), stock INTEGER NOT NULL CHECK(stock>=0), category_id BIGINT NOT NULL REFERENCES category(id));
CREATE INDEX idx_book_seller ON book(seller_id);
CREATE INDEX idx_book_category ON book(category_id);
